8	/// Extension of [`Erc20`] that allows token holders to destroy both
9	/// their own tokens and those that they have an allowance for,
10	/// in a way that can be recognized off-chain (via event analysis).
11	#[public]
12	pub trait IErc20Burnable {
13	    /// The error type associated to this ERC-20 Burnable trait implementation.
14	    type Error: Into<alloc::vec::Vec<u8>>;
15	
16	    /// Destroys a `value` amount of tokens from the caller, lowering the total
17	    /// supply.
18	    ///
19	    /// # Arguments
20	    ///
21	    /// * `&mut self` - Write access to the contract's state.
22	    /// * `value` - Amount to be burnt.
23	    ///
24	    /// # Errors
25	    ///
26	    /// * [`erc20::Error::InsufficientBalance`] - If the `from` address doesn't
27	    ///   have enough tokens.
28	    ///
29	    /// # Events
30	    ///
31	    /// * [`erc20::Transfer`].
32	    fn burn(&mut self, value: U256) -> Result<(), Self::Error>;
33	
34	    /// Destroys a `value` amount of tokens from `account`, lowering the total
35	    /// supply.
36	    ///
37	    /// # Arguments
38	    ///
39	    /// * `&mut self` - Write access to the contract's state.
40	    /// * `account` - Owner's address.
41	    /// * `value` - Amount to be burnt.
42	    ///
43	    /// # Errors
44	    ///
45	    /// * [`erc20::Error::InsufficientAllowance`] - If not enough allowance is
46	    ///   available.
47	    /// * [`erc20::Error::InvalidSender`] - If the `from` address is
48	    ///   [`Address::ZERO`].
49	    /// * [`erc20::Error::InsufficientBalance`] - If the `from` address doesn't
50	    ///   have enough tokens.
51	    ///
52	    /// # Events
53	    ///
54	    /// * [`erc20::Transfer`].
55	    fn burn_from(
56	        &mut self,
57	        account: Address,
58	        value: U256,
59	    ) -> Result<(), Self::Error>;
60	}
61	
62	#[public]
63	impl IErc20Burnable for Erc20 {
64	    type Error = erc20::Error;
65	
66	    fn burn(&mut self, value: U256) -> Result<(), Self::Error> {
67	        self._burn(self.vm().msg_sender(), value)
68	    }
69	
70	    fn burn_from(
71	        &mut self,
72	        account: Address,
73	        value: U256,
74	    ) -> Result<(), Self::Error> {
75	        self._spend_allowance(account, self.vm().msg_sender(), value)?;
76	        self._burn(account, value)
77	    }
78	}
