1	//! Capped Contract.
2	//!
3	//! Extension of ERC-20 standard that adds a cap to the supply of tokens.
4	//!
5	//! Note that they will not be capped by simply including this module,
6	//! but only once the checks are put in place.
7	
8	use alloc::{vec, vec::Vec};
9	
10	use alloy_primitives::U256;
11	use openzeppelin_stylus_proc::interface_id;
12	pub use sol::*;
13	use stylus_sdk::{stylus_core::calls::errors::MethodError, prelude::*, storage::StorageU256};
14	
15	#[cfg_attr(coverage_nightly, coverage(off))]
16	mod sol {
17	    use alloy_sol_macro::sol;
18	
19	    sol! {
20	        /// Indicates an error related to the operation that failed
21	        /// because `total_supply` exceeded the `cap`.
22	        #[derive(Debug)]
23	        #[allow(missing_docs)]
24	        error ERC20ExceededCap(uint256 increased_supply, uint256 cap);
25	
26	        /// Indicates an error related to the operation that failed
27	        /// because the supplied `cap` is not a valid cap value.
28	        #[derive(Debug)]
29	        #[allow(missing_docs)]
30	        error ERC20InvalidCap(uint256 cap);
31	    }
32	}
33	
34	/// A Capped error.
35	#[derive(SolidityError, Debug)]
36	pub enum Error {
37	    /// Indicates an error related to the operation that failed
38	    /// because `total_supply` exceeded the `cap`.
39	    ExceededCap(ERC20ExceededCap),
40	    /// Indicates an error related to the operation that failed
41	    /// because the supplied `cap` is not a valid cap value.
42	    InvalidCap(ERC20InvalidCap)}
43	
44	impl MethodError for Error {
45	    fn encode(self) -> alloc::vec::Vec<u8> {
46	        self.into()
47	    }
48	}
49	
50	/// State of a [`Capped`] Contract.
51	#[storage]
52	pub struct Capped {
53	    /// A cap to the supply of tokens.
54	    pub(crate) cap: StorageU256}
55	
56	/// Interface for the token supply cap logic.
57	#[interface_id]
58	#[public]
59	pub trait ICapped {
60	    /// Returns the cap on the token's total supply.
61	    #[must_use]
62	    fn cap(&self) -> U256;
63	}
64	
65	#[public]
66	#[implements(ICapped)]
67	impl Capped {
68	    /// Constructor.
69	    ///
70	    /// # Arguments
71	    ///
72	    /// * `&mut self` - Write access to the contract's state.
73	    /// * `cap` - The token supply cap.
74	    ///
75	    /// # Errors
76	    ///
77	    /// * [`Error::InvalidCap`] - If cap is [`U256::ZERO`].
78	    #[constructor]
79	    pub fn constructor(&mut self, cap: U256) -> Result<(), Error> {
80	        if cap.is_zero() {
81	            return Err(Error::InvalidCap(ERC20InvalidCap { cap }));
82	        }
83	        self.cap.set(cap);
84	        Ok(())
85	    }
86	}
87	
88	#[public]
89	impl ICapped for Capped {
90	    fn cap(&self) -> U256 {
91	        self.cap.get()
92	    }
93	}
