113	        assert_eq!(contract.sender(alice).cap(), value);
114	
115	        let value = uint!(0_U256);
116	        let err = contract
117	            .sender(alice)
118	            .constructor(value)
119	            .expect_err("should return error");
120	        assert!(matches!(
121	            err,
122	            Error::InvalidCap(ERC20InvalidCap { cap }) if cap == value
123	        ));
124	    }
