//! Defines host environment methods Stylus SDK contracts have access to.
extern crate alloc;

use alloc::vec::Vec;

use alloy_primitives::{Address, B256, U256};
use alloy_sol_types::{abi::token::WordToken, SolEvent, TopicList};
