47	/// An [`Erc20Wrapper`] error.
48	#[derive(SolidityError, Debug)]
49	pub enum Error {
50	    /// Indicates an error related to the current balance of `sender`. Used in
51	    /// transfers.
52	    InsufficientBalance(erc20::ERC20InsufficientBalance),
53	    /// Indicates a failure with the token `sender`. Used in transfers.
54	    InvalidSender(erc20::ERC20InvalidSender),
55	    /// Indicates a failure with the token `receiver`. Used in transfers.
56	    InvalidReceiver(erc20::ERC20InvalidReceiver),
57	    /// Indicates a failure with the `spender`’s `allowance`. Used in
58	    /// transfers.
59	    InsufficientAllowance(erc20::ERC20InsufficientAllowance),
60	    /// Indicates a failure with the `spender` to be approved. Used in
61	    /// approvals.
62	    InvalidSpender(erc20::ERC20InvalidSpender),
63	    /// Indicates a failure with the `approver` of a token to be approved. Used
64	    /// in approvals. approver Address initiating an approval operation.
65	    InvalidApprover(erc20::ERC20InvalidApprover),
66	    /// An operation with an ERC-20 token failed.
67	    SafeErc20FailedOperation(safe_erc20::SafeErc20FailedOperation),
68	    /// Indicates a failed [`ISafeErc20::safe_decrease_allowance`] request.
69	    SafeErc20FailedDecreaseAllowance(
70	        safe_erc20::SafeErc20FailedDecreaseAllowance,
71	    ),
72	    /// The underlying token couldn't be wrapped.
73	    InvalidUnderlying(ERC20InvalidUnderlying)}
74	
75	impl From<erc20::Error> for Error {
76	    fn from(value: erc20::Error) -> Self {
77	        match value {
78	            erc20::Error::InsufficientBalance(e) => {
79	                Error::InsufficientBalance(e)
80	            }
81	            erc20::Error::InvalidSender(e) => Error::InvalidSender(e),
82	            erc20::Error::InvalidReceiver(e) => Error::InvalidReceiver(e),
83	            erc20::Error::InsufficientAllowance(e) => {
84	                Error::InsufficientAllowance(e)
85	            }
86	            erc20::Error::InvalidSpender(e) => Error::InvalidSpender(e),
87	            erc20::Error::InvalidApprover(e) => Error::InvalidApprover(e)}
88	    }
89	}
