118	/// ERC-20 Wrapper Standard Interface
119	#[interface_id]
120	#[public]
121	pub trait IErc20Wrapper {
122	    /// The error type associated to the trait implementation.
123	    type Error: Into<alloc::vec::Vec<u8>>;
124	
125	    /// Returns the number of decimals used to get its user representation.
126	    ///
127	    /// # Arguments
128	    ///
129	    /// * `&self` - Read access to the contract's state.
130	    ///
131	    /// # Examples
132	    ///
133	    /// ```rust,ignore
134	    /// fn decimals(&self) -> U8 {
135	    ///     self.erc20_wrapper.decimals()
136	    /// }
137	    /// ```
138	    #[must_use]
139	    fn decimals(&self) -> U8;
140	
141	    /// Returns the address of the underlying ERC-20 token that is being
142	    /// wrapped.
143	    ///
144	    /// # Arguments
145	    ///
146	    /// * `&self` - Read access to the contract's state.
147	    ///
148	    /// # Examples
149	    ///
150	    /// ```rust,ignore
151	    /// fn underlying(&self) -> Address {
152	    ///     self.erc20_wrapper.underlying()
153	    /// }
154	    /// ```
155	    #[must_use]
156	    fn underlying(&self) -> Address;
157	
158	    /// Allow a user to deposit underlying tokens and mint the corresponding
159	    /// number of wrapped tokens.
160	    ///
161	    /// # Arguments
162	    ///
163	    /// * `&mut self` - Write access to the contract's state.
164	    /// * `account` - The account to deposit tokens to.
165	    /// * `value` - The amount of tokens to deposit.
166	    ///
167	    /// # Errors
168	    ///
169	    /// * [`Error::InvalidSender`] - If the `self.vm().msg_sender()`'s address is the
170	    ///   `contract:address()`.
171	    /// * [`Error::InvalidReceiver`] - If the `account` address is a
172	    ///   `contract:address()`.
173	    /// * [`Error::SafeErc20FailedOperation`] - If caller lacks sufficient
174	    ///   balance or hasn't approved enough tokens to the [`Erc20Wrapper`]
175	    ///   contract.
176	    /// * [`Error::InvalidReceiver`] - If the `account` address is
177	    ///   [`Address::ZERO`].
178	    ///
179	    /// # Panics
180	    ///
181	    /// * If [`Erc20::_mint`] operation panics.
182	    fn deposit_for(
183	        &mut self,
184	        account: Address,
185	        value: U256,
186	    ) -> Result<bool, Self::Error>;
187	
188	    /// Allow a user to burn a number of wrapped tokens and withdraw the
189	    /// corresponding number of underlying tokens.
190	    ///
191	    /// # Arguments
192	    ///
193	    /// * `&mut self` - Write access to the contract's state.
194	    /// * `account` - The account to withdraw tokens from.
195	    /// * `value` - The amount of tokens to withdraw.
196	    ///
197	    /// # Errors
198	    ///
199	    /// * [`Error::InvalidReceiver`] - If the `account`'s address is a
200	    ///   `contract:address()`.
201	    /// * [`Error::InvalidSender`] - If the `from` address is [`Address::ZERO`].
202	    /// * [`Error::InsufficientBalance`] - If the `from` address doesn't have
203	    ///   enough tokens.
204	    /// * [`Error::SafeErc20FailedOperation`] - If the [`Erc20Wrapper`] contract
205	    ///   lacks sufficient balance.
206	    fn withdraw_to(
207	        &mut self,
208	        account: Address,
209	        value: U256,
210	    ) -> Result<bool, Self::Error>;
211	}
