213	/// NOTE: Implementation of [`TopLevelStorage`] to be able use `&mut self` when
214	/// calling other contracts and not `&mut (impl TopLevelStorage +
215	/// BorrowMut<Self>)`. Should be fixed in the future by the Stylus team.
216	unsafe impl TopLevelStorage for Erc20Wrapper {}
217	
218	impl Erc20Wrapper {
219	    /// See [`IErc20Wrapper::decimals`].
220	    #[must_use]
221	    pub fn decimals(&self) -> U8 {
222	        U8::from(
223	            IErc20MetadataInterface::new(self.underlying())
224	                .decimals(self)
225	                .unwrap_or(DEFAULT_DECIMALS),
226	        )
227	    }
228	
229	    /// See [`IErc20Wrapper::underlying`].
230	    #[must_use]
231	    pub fn underlying(&self) -> Address {
232	        self.underlying.get()
233	    }
234	
235	    /// See [`IErc20Wrapper::deposit_for`].
236	    #[allow(clippy::missing_errors_doc)]
237	    pub fn deposit_for(
238	        &mut self,
239	        account: Address,
240	        value: U256,
241	        erc20: &mut Erc20,
242	    ) -> Result<bool, Error> {
243	        let contract_address = self.vm().contract_address();
244	        let sender = self.vm().msg_sender();
245	
246	        if sender == contract_address {
247	            return Err(erc20::ERC20InvalidSender { sender }.into());
248	        }
249	
250	        if account == contract_address {
251	            return Err(
252	                erc20::ERC20InvalidReceiver { receiver: account }.into()
253	            );
254	        }
255	
256	        self.safe_erc20.safe_transfer_from(
257	            self.underlying(),
258	            sender,
259	            contract_address,
260	            value,
261	        )?;
262	
263	        erc20._mint(account, value)?;
264	
265	        Ok(true)
266	    }
267	
268	    /// See [`IErc20Wrapper::withdraw_to`].
269	    #[allow(clippy::missing_errors_doc)]
270	    pub fn withdraw_to(
271	        &mut self,
272	        account: Address,
273	        value: U256,
274	        erc20: &mut Erc20,
275	    ) -> Result<bool, Error> {
276	        if account == self.vm().contract_address() {
277	            return Err(
278	                erc20::ERC20InvalidReceiver { receiver: account }.into()
279	            );
280	        }
281	
282	        erc20._burn(self.vm().msg_sender(), value)?;
283	
284	        self.safe_erc20.safe_transfer(self.underlying(), account, value)?;
285	
286	        Ok(true)
287	    }
288	}
