290	#[public]
291	impl Erc20Wrapper {
292	    /// Constructor.
293	    ///
294	    /// # Arguments
295	    ///
296	    /// * `&mut self` - Write access to the contract's state.
297	    /// * `underlying_token` - The wrapped token.
298	    ///
299	    /// # Errors
300	    ///
301	    /// * [`Error::InvalidUnderlying`] - If underlying token is this contract.
302	    #[constructor]
303	    pub fn constructor(
304	        &mut self,
305	        underlying_token: Address,
306	    ) -> Result<(), Error> {
307	        if underlying_token == self.vm().contract_address() {
308	            return Err(Error::InvalidUnderlying(ERC20InvalidUnderlying {
309	                token: underlying_token}));
310	        }
311	        self.underlying.set(underlying_token);
312	        Ok(())
313	    }
314	}
