201	    /// Fetches the denominator with which to interpret the fee set
202	    /// in [`Self::_set_token_royalty`] and [`Self::_set_default_royalty`] as a
203	    /// fraction of the sale price.
204	    ///
205	    /// Defaults to 10000 so fees are expressed in basis points, but
206	    /// may be customized in the constructor.
207	    ///
208	    /// # Arguments
209	    ///
210	    /// * `&self` - Read access to the contract's state.
211	    #[must_use]
212	    pub fn _fee_denominator(&self) -> U96 {
213	        self.fee_denominator.get()
214	    }
215	
216	    /// Sets the royalty information that all ids in this contract
217	    /// will default to.
218	    ///
219	    /// # Arguments
220	    ///
221	    /// * `&mut self` - Write access to the contract's state.
222	    /// * `receiver` - Address to receive the royalty.
223	    /// * `fee_numerator` - Fraction of royalty to be given to receiver.
224	    ///
225	    /// # Errors
226	    ///
227	    /// * [`Error::InvalidDefaultRoyalty`] - If `fee_numerator` > denominator.
228	    /// * [`Error::InvalidDefaultRoyaltyReceiver`] - If `receiver` is
229	    ///   [`Address::ZERO`].
230	    pub fn _set_default_royalty(
231	        &mut self,
232	        receiver: Address,
233	        fee_numerator: U96,
234	    ) -> Result<(), Error> {
235	        let denominator = self._fee_denominator();
236	
237	        if fee_numerator > denominator {
238	            return Err(Error::InvalidDefaultRoyalty(
239	                ERC2981InvalidDefaultRoyalty {
240	                    numerator: U256::from(fee_numerator),
241	                    denominator: U256::from(denominator)},
242	            ));
243	        }
244	
245	        if receiver.is_zero() {
246	            return Err(Error::InvalidDefaultRoyaltyReceiver(
247	                ERC2981InvalidDefaultRoyaltyReceiver { receiver },
248	            ));
249	        }
250	
251	        self.default_royalty_info.receiver.set(receiver);
252	        self.default_royalty_info.royalty_fraction.set(fee_numerator);
253	
254	        Ok(())
255	    }
256	
257	    /// Removes default royalty information.
258	    ///
259	    /// # Arguments
260	    ///
261	    /// * `&mut self` - Write access to the contract's state.
262	    pub fn _delete_default_royalty(&mut self) {
263	        self.default_royalty_info.erase();
264	    }
265	
266	    /// Sets the royalty information for a specific `token_id`,
267	    /// overriding the global default.
268	    ///
269	    /// # Arguments
270	    ///
271	    /// * `&mut self` - Write access to the contract's state.
272	    /// * `token_id` - Id of a token.
273	    /// * `receiver` - Address to receive the royalty.
274	    /// * `fee_numerator` - Fraction of royalty to be given to receiver.
275	    ///
276	    /// # Errors
277	    ///
278	    /// * [`Error::InvalidTokenRoyalty`] - If `fee_numerator` >
279	    ///   [`Self::_fee_denominator()`].
280	    /// * [`Error::InvalidTokenRoyaltyReceiver`] - If `receiver` is
281	    ///   [`Address::ZERO`].
282	    pub fn _set_token_royalty(
283	        &mut self,
284	        token_id: U256,
285	        receiver: Address,
286	        fee_numerator: U96,
287	    ) -> Result<(), Error> {
288	        let denominator = self._fee_denominator();
289	        if fee_numerator > denominator {
290	            return Err(Error::InvalidTokenRoyalty(
291	                ERC2981InvalidTokenRoyalty {
292	                    token_id,
293	                    numerator: U256::from(fee_numerator),
294	                    denominator: U256::from(denominator)},
295	            ));
296	        }
297	
298	        if receiver.is_zero() {
299	            return Err(Error::InvalidTokenRoyaltyReceiver(
300	                ERC2981InvalidTokenRoyaltyReceiver { token_id, receiver },
301	            ));
302	        }
303	
304	        let mut token_royalty_info = self.token_royalty_info.setter(token_id);
305	        token_royalty_info.receiver.set(receiver);
306	        token_royalty_info.royalty_fraction.set(fee_numerator);
307	
308	        Ok(())
309	    }
310	
311	    /// Resets royalty information for the token id back to the
312	    /// global default.
313	    ///
314	    /// # Arguments
315	    ///
316	    /// * `&mut self` - Write access to the contract's state.
317	    /// * `token_id` - Id of the token.
318	    pub fn _reset_token_royalty(&mut self, token_id: U256) {
319	        self.token_royalty_info.delete(token_id);
320	    }
321	}
