    use alloy_primitives::{address, aliases::B32, uint};
    use alloy_sol_types::{sol, SolCall, SolEvent, SolValue};
    use stylus_sdk::testing::TestVM;

    use super::*;
    use crate::test_utils::ALICE;

    sol! {
        /// The calls that the wrapper makes to its underlying token.
        interface IERC20 {
            function balanceOf(address account) external view returns (uint256);
            function decimals() external view returns (uint8);
            function transfer(address to, uint256 value) external returns (bool);
            function transferFrom(address from, address to, uint256 value) external returns (bool);
        }
    }

    const DUMMY_TEST_DECIMALS: u8 = 12;

    /// Address of the underlying token of the wrapper.
    const UNDERLYING: Address =
        address!("0x00000000000000000000000000000000000e2c20");

    /// The ERC-20 token wrapped by the contract under test.
    ///
    /// A [`TestVM`] cannot call into another contract, so the token lives in
    /// its own VM and the calls that the wrapper makes to it are mocked with
    /// the outcome of the same calls on the token.
    struct Underlying {
        vm: TestVM,
        token: Erc20,
    }

    impl Underlying {
        /// Deploys the token at [`UNDERLYING`], where `caller` sees a contract.
        fn deploy(caller: &TestVM) -> Self {
            let vm = TestVM::default();
            vm.set_contract_address(UNDERLYING);
            let token = Erc20::from(&vm);

            caller.set_code(UNDERLYING, vec![1]);

            Self { vm, token }
        }

        /// Mocks the `transferFrom` call that `caller` makes to the token.
        fn mock_transfer_from(
            &mut self,
            caller: &TestVM,
            from: Address,
            to: Address,
            value: U256,
        ) {
            self.vm.set_sender(caller.contract_address());
            let result = self.token.transfer_from(from, to, value);
            caller.mock_call(
                UNDERLYING,
                IERC20::transferFromCall { from, to, value }.abi_encode(),
                U256::ZERO,
                Self::response(result),
            );
        }

        /// Mocks the `transfer` call that `caller` makes to the token.
        fn mock_transfer(&mut self, caller: &TestVM, to: Address, value: U256) {
            self.vm.set_sender(caller.contract_address());
            let result = self.token.transfer(to, value);
            caller.mock_call(
                UNDERLYING,
                IERC20::transferCall { to, value }.abi_encode(),
                U256::ZERO,
                Self::response(result),
            );
        }

        /// Mocks the `balanceOf` call that `caller` makes to the token.
        fn mock_balance_of(&self, caller: &TestVM, account: Address) {
            caller.mock_static_call(
                UNDERLYING,
                IERC20::balanceOfCall { account }.abi_encode(),
                Self::response(Ok(self.token.balance_of(account))),
            );
        }

        /// Encodes the outcome of a call on the token as the response to the
        /// call.
        fn response<T: SolValue>(
            result: Result<T, erc20::Error>,
        ) -> Result<Vec<u8>, Vec<u8>> {
            result.map(|value| value.abi_encode()).map_err(Into::into)
        }
    }

    /// Asserts that `vm` emitted the `event`.
    #[track_caller]
    fn assert_emitted<E: SolEvent + Debug>(vm: &TestVM, event: &E) {
        let log = event.encode_log_data();
        let expected = (log.topics().to_vec(), log.data.to_vec());
        assert!(
            vm.get_emitted_logs().contains(&expected),
            "event was not emitted: {event:?}"
        );
    }

    #[storage]
    struct Erc20WrapperTestExample {
        wrapper: Erc20Wrapper,
        erc20: Erc20,
    }

    #[public]
    #[implements(IErc20Wrapper<Error = Error>)]
    impl Erc20WrapperTestExample {
        #[constructor]
        fn constructor(
            &mut self,
            underlying_token: Address,
        ) -> Result<(), Error> {
            self.wrapper.constructor(underlying_token)
        }

        fn recover(&mut self, account: Address) -> Result<U256, Error> {
            self.wrapper._recover(account, &mut self.erc20)
        }
    }

    #[public]
    impl IErc20Wrapper for Erc20WrapperTestExample {
        type Error = Error;

        fn decimals(&self) -> U8 {
            self.wrapper.decimals()
        }

        fn underlying(&self) -> Address {
            self.wrapper.underlying()
        }

        fn deposit_for(
            &mut self,
            account: Address,
            value: U256,
        ) -> Result<bool, Error> {
            self.wrapper.deposit_for(account, value, &mut self.erc20)
        }

}

#[cfg_attr(coverage_nightly, coverage(off))]
#[cfg(test)]
mod tests {
    use alloy_primitives::{address, uint};
    use stylus_sdk::testing::TestVM;

    use super::*;
    use crate::{
        test_utils::{ALICE, BOB},
        token::erc20::{Erc20, IErc20},
    };

    /// Address of the ERC-20 token that the examples interact with.
    const TOKEN: Address =
        address!("0x00000000000000000000000000000000000e2c20");

    #[storage]
    #[entrypoint]
    struct SafeErc20Example {
        safe_erc20: SafeErc20,
    }

    #[public]
    #[implements(ISafeErc20<Error = Error>)]
    impl SafeErc20Example {}

    #[public]
    impl ISafeErc20 for SafeErc20Example {
        type Error = Error;

        fn safe_transfer(
            &mut self,
            token: Address,
            to: Address,
            value: U256,
        ) -> Result<(), Self::Error> {
            self.safe_erc20.safe_transfer(token, to, value)
        }

        fn safe_transfer_from(
            &mut self,
            token: Address,
            from: Address,
            to: Address,
            value: U256,
        ) -> Result<(), Self::Error> {
            self.safe_erc20.safe_transfer_from(token, from, to, value)
        }

        fn try_safe_transfer(
            &mut self,
            token: Address,
            to: Address,
            value: U256,
        ) -> bool {
    ///
    /// A [`TestVM`] cannot call into another contract, so the token lives in
    /// its own VM and the calls that the contract under test makes to it are
    /// mocked with the response of the token.
    fn deploy_token(caller_vm: &TestVM) -> (TestVM, Erc20) {
        let vm = TestVM::default();
        vm.set_contract_address(TOKEN);
        let erc20 = Erc20::from(&vm);

        // Make `TOKEN` look like a contract for the caller.
        caller_vm.set_code(TOKEN, vec![1]);

        (vm, erc20)
    }

    #[test]
    fn try_safe_transfer() {
        let vm = TestVM::default();
        let mut contract = SafeErc20Example::from(&vm);
        let (token_vm, mut erc20) = deploy_token(&vm);

        let token = TOKEN;
        let value = U256::from(1);
        erc20._mint(vm.contract_address(), value).unwrap();

        let balance = erc20.balance_of(vm.contract_address());
        assert_eq!(balance, value);
        let balance = erc20.balance_of(ALICE);
        assert_eq!(balance, U256::ZERO);

        // The contract calls `transfer` of the token on its own behalf.
        token_vm.set_sender(vm.contract_address());
        let success = erc20.transfer(ALICE, value).unwrap();
        vm.mock_call(
            token,
            IERC20::transferCall { to: ALICE, value }.abi_encode(),
            U256::ZERO,
            Ok(Bool::abi_encode(&success)),
        );

        vm.set_sender(ALICE);
        let result = contract.try_safe_transfer(token, ALICE, value);
        assert!(result);

        let balance = erc20.balance_of(vm.contract_address());
        assert_eq!(balance, U256::ZERO);
        let balance = erc20.balance_of(ALICE);
        assert_eq!(balance, value);
    }

    #[test]
    fn try_safe_transfer_from() {
        let vm = TestVM::default();
        let mut contract = SafeErc20Example::from(&vm);
        let (token_vm, mut erc20) = deploy_token(&vm);

        let token = TOKEN;
        let value = U256::from(1);
        erc20._mint(ALICE, value).unwrap();
        token_vm.set_sender(ALICE);
        erc20.approve(vm.contract_address(), value).unwrap();

        let balance = erc20.balance_of(ALICE);
        assert_eq!(balance, value);
        let balance = erc20.balance_of(BOB);
        assert_eq!(balance, U256::ZERO);

        // The contract calls `transferFrom` of the token on its own behalf.
        token_vm.set_sender(vm.contract_address());
        let success = erc20.transfer_from(ALICE, BOB, value).unwrap();
        vm.mock_call(
            token,
            IERC20::transferFromCall { from: ALICE, to: BOB, value }
                .abi_encode(),
            U256::ZERO,
            Ok(Bool::abi_encode(&success)),
        );

        vm.set_sender(ALICE);
        let result = contract.try_safe_transfer_from(token, ALICE, BOB, value);
        assert!(result);

        let balance = erc20.balance_of(ALICE);
        assert_eq!(balance, U256::ZERO);
        let balance = erc20.balance_of(BOB);
        assert_eq!(balance, value);
    }

    #[test]
    fn safe_decrease_allowance_reverts_on_no_code_address() {
        let vm = TestVM::default();
        let mut contract = SafeErc20Example::from(&vm);

        let no_code_addr = ALICE;
        vm.set_sender(ALICE);
        let err = contract
            .safe_decrease_allowance(no_code_addr, BOB, uint!(1_U256))
            .expect_err("should revert on no code address");
        assert!(matches!(
        err,
        Error::SafeErc20FailedOperation(
            SafeErc20FailedOperation {
                token}) if token == no_code_addr
        ));
    }

    #[test]
    fn safe_increase_allowance_reverts_on_no_code_address() {
        let vm = TestVM::default();
        let mut contract = SafeErc20Example::from(&vm);

        let no_code_addr = ALICE;
        vm.set_sender(ALICE);
        let err = contract
            .safe_increase_allowance(no_code_addr, BOB, uint!(1_U256))
            .expect_err("should revert on no code address");
        assert!(matches!(
        err,
        Error::SafeErc20FailedOperation(
            SafeErc20FailedOperation {
                token}) if token == no_code_addr
        ));
    }
}

